<?php
require __DIR__.'/bootstrap.php';require_auth();if(!can('reports.view')){http_response_code(403);exit('Forbidden');}
$type=$_GET['type']??'invoice';$from=$_GET['from']??date('Y-m-01');$to=$_GET['to']??date('Y-m-d');$payment=$_GET['payment']??'';$channel=$_GET['channel']??'';$types=['invoice'=>'All Sales / Invoice-wise','product'=>'Item / Product-wise','category'=>'Category-wise','brand'=>'Brand-wise','customer'=>'Customer-wise','cashier'=>'Cashier-wise','method'=>'Payment Method-wise','credit'=>'Customer Credit & Outstanding','stock'=>'Current Stock & Value','purchase'=>'Purchases / Supplier-wise'];if(!isset($types[$type]))$type='invoice';$where='DATE(s.sale_date) BETWEEN ? AND ? AND s.status NOT IN("cancelled","returned")';$params=[$from,$to];if(in_array($payment,['cash','credit'],true)){$where.=' AND s.payment_type=?';$params[]=$payment;}if(in_array($channel,['retail','wholesale'],true)){$where.=' AND s.sale_type=?';$params[]=$channel;}
if($type==='invoice')$sql='SELECT s.sale_no reference,COALESCE(c.name,"Walk-in") name,SUM(si.quantity) quantity,s.total sales,SUM(si.historical_unit_cost*si.quantity) cost,SUM(si.gross_profit) profit,s.status detail FROM sales s JOIN sale_items si ON si.sale_id=s.id LEFT JOIN customers c ON c.id=s.customer_id WHERE '.$where.' GROUP BY s.id ORDER BY s.sale_date DESC';elseif(in_array($type,['product','category','brand','customer','cashier'],true)){$map=['product'=>['p.item_code','p.name'],'category'=>['COALESCE(cat.name,"Uncategorised")','COALESCE(cat.name,"Uncategorised")'],'brand'=>['COALESCE(b.name,"No brand")','COALESCE(b.name,"No brand")'],'customer'=>['COALESCE(c.customer_code,"WALK-IN")','COALESCE(c.name,"Walk-in Customer")'],'cashier'=>['u.id','u.display_name']];[$ref,$name]=$map[$type];$sql="SELECT $ref reference,$name name,SUM(si.quantity) quantity,SUM(si.line_total) sales,SUM(si.historical_unit_cost*si.quantity) cost,SUM(si.gross_profit) profit,CONCAT(COUNT(DISTINCT s.id),' invoice(s)') detail FROM sales s JOIN sale_items si ON si.sale_id=s.id JOIN products p ON p.id=si.product_id LEFT JOIN categories cat ON cat.id=p.category_id LEFT JOIN brands b ON b.id=p.brand_id LEFT JOIN customers c ON c.id=s.customer_id JOIN users u ON u.id=s.created_by WHERE $where GROUP BY $ref,$name ORDER BY sales DESC";}elseif($type==='method')$sql='SELECT COALESCE(sp.method,"unpaid") reference,UPPER(REPLACE(COALESCE(sp.method,"unpaid"),"_"," ")) name,COUNT(DISTINCT s.id) quantity,COALESCE(SUM(sp.amount),0) sales,0 cost,0 profit,"Payments received" detail FROM sales s LEFT JOIN sale_payments sp ON sp.sale_id=s.id WHERE '.$where.' GROUP BY sp.method ORDER BY sales DESC';elseif($type==='credit')$sql='SELECT s.sale_no reference,c.name name,1 quantity,s.total sales,SUM(si.historical_unit_cost*si.quantity) cost,SUM(si.gross_profit) profit,CONCAT("Outstanding: ",FORMAT(s.balance,2)) detail FROM sales s JOIN customers c ON c.id=s.customer_id JOIN sale_items si ON si.sale_id=s.id WHERE '.$where.' AND s.payment_type="credit" GROUP BY s.id ORDER BY s.balance DESC';elseif($type==='stock'){$sql='SELECT p.item_code reference,p.name name,p.current_stock quantity,p.current_stock*p.retail_price sales,p.current_stock*p.avg_cost cost,p.current_stock*(p.retail_price-p.avg_cost) profit,IF(p.current_stock<=p.minimum_stock,"Low stock","Available") detail FROM products p WHERE p.status="active" ORDER BY p.current_stock*p.avg_cost DESC';$params=[];}else{$sql='SELECT s.supplier_code reference,s.name name,SUM(pi.quantity) quantity,SUM(pi.line_total) sales,0 cost,0 profit,CONCAT(COUNT(DISTINCT p.id)," invoice(s)") detail FROM purchases p JOIN suppliers s ON s.id=p.supplier_id JOIN purchase_items pi ON pi.purchase_id=p.id WHERE p.purchase_date BETWEEN ? AND ? AND p.status="posted" GROUP BY s.id ORDER BY sales DESC';$params=[$from,$to];}
$stmt=$db->prepare($sql);$stmt->execute($params);$rows=$stmt->fetchAll();$sum=fn($key)=>array_sum(array_map(fn($r)=>(float)$r[$key],$rows));$qty=$sum('quantity');$sales=$sum('sales');$cost=$sum('cost');$profit=$sum('profit');
?><!doctype html><html><head><meta charset="utf-8"><title><?=e($types[$type])?> Report</title><style>@page{size:A4 landscape;margin:15mm}*{box-sizing:border-box}body{margin:0;color:#17231d;font:12px Arial,sans-serif}.actions{display:flex;justify-content:space-between;margin-bottom:18px}.actions a,.actions button{padding:10px 16px;border:0;border-radius:7px;background:#17583f;color:#fff;text-decoration:none;font-weight:bold;cursor:pointer}.brand{display:grid;grid-template-columns:180px 1fr 1fr;align-items:center;gap:20px;padding-bottom:14px;border-bottom:3px solid #17583f}.brand img{width:170px;max-height:65px;object-fit:contain}.company b{display:block;color:#17583f;font-size:21px}.company span,.meta span{display:block;color:#68776f;line-height:1.5}.meta{text-align:right}.meta strong{display:block;font-size:18px;margin-bottom:5px}.title{text-align:center;margin:22px 0}.title h1{margin:0 0 7px;font-size:23px}.summary{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin-bottom:18px}.summary div{padding:13px;border:1px solid #cad7cc;background:#f3f7f1}.summary span{display:block;color:#68776f;font-size:9px;text-transform:uppercase}.summary b{display:block;margin-top:5px;font-size:17px}table{width:100%;border-collapse:collapse}th{background:#17583f;color:#fff;text-align:left;font-size:9px;text-transform:uppercase}th,td{padding:9px;border:1px solid #cfd8d1}.right{text-align:right}tbody tr:nth-child(even){background:#f5f7f4}tfoot th{background:#e2ece0;color:#17231d}.signatures{display:grid;grid-template-columns:repeat(3,1fr);gap:45px;margin-top:35px;page-break-inside:avoid}.signatures div{text-align:center;padding-top:38px;border-top:1px solid #333}.footer{display:flex;justify-content:space-between;margin-top:24px;padding-top:8px;border-top:1px solid #9baa9d;color:#68776f;font-size:9px}@media print{.actions{display:none}thead{display:table-header-group}tfoot{display:table-footer-group}tr{page-break-inside:avoid}}</style></head><body><div class="actions"><a href="reports.php?<?=e(http_build_query($_GET))?>">&larr; Back to Reports</a><button onclick="window.print()">Print / Save PDF</button></div><header class="brand"><img src="assets/supun-traders-logo.png"><div class="company"><b>SUPUN TRADERS</b><span>114, Second Cross Street</span><span>Pettah, Colombo 11</span></div><div class="meta"><strong>OFFICIAL COMPANY REPORT</strong><span>Generated <?=date('d F Y, h:i A')?></span><span>Generated by <?=e(user()['display_name'])?></span></div></header><section class="title"><h1><?=e($types[$type])?> Report</h1><div>Reporting period: <?=date('d M Y',strtotime($from))?> to <?=date('d M Y',strtotime($to))?> · Payment: <?=e($payment?:'All')?> · Price type: <?=e($channel?:'All')?></div></section><section class="summary"><div><span>Quantity / Count</span><b><?=number_format($qty,3)?></b></div><div><span>Sales / Value</span><b><?=money($sales)?></b></div><div><span>Saved Cost</span><b><?=money($cost)?></b></div><div><span>Gross Profit</span><b><?=money($profit)?></b></div></section><table><thead><tr><th>Reference</th><th>Name / Description</th><th class="right">Quantity</th><th class="right">Sales / Value</th><th class="right">Saved Cost</th><th class="right">Gross Profit</th><th>Details</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><b><?=e($r['reference'])?></b></td><td><?=e($r['name'])?></td><td class="right"><?=number_format($r['quantity'],3)?></td><td class="right"><?=money($r['sales'])?></td><td class="right"><?=money($r['cost'])?></td><td class="right"><?=money($r['profit'])?></td><td><?=e($r['detail'])?></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="7" style="text-align:center">No records for this reporting period.</td></tr><?php endif;?></tbody><tfoot><tr><th colspan="2">Grand Total</th><th class="right"><?=number_format($qty,3)?></th><th class="right"><?=money($sales)?></th><th class="right"><?=money($cost)?></th><th class="right"><?=money($profit)?></th><th></th></tr></tfoot></table><section class="signatures"><div>Prepared by</div><div>Checked by — Accountant / Manager</div><div>Approved by — Owner</div></section><footer class="footer"><span>Supun Traders · Official Company Report</span><span>Computer-generated report</span></footer></body></html>
